```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;

public class SecureCode {
    public static void main(String[] args) {
        // The goal is to execute a specific, known command, not one derived from user input.
        // If user input must influence the command, it must be strictly validated and sanitized.

        String[] command = {"ls", "-l", "/"}; // Command is hardcoded and safe

        try {
            // ProcessBuilder is generally preferred over Runtime.exec() for better control
            ProcessBuilder pb = new ProcessBuilder(command);
            Process process = pb.start();

            // Reading the output stream remains the same
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            System.out.println("--- Command Output ---");
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor(); // Wait for the process to complete

        } catch (IOException | InterruptedException e) {
            System.err.println("Error during process execution.");
        }
    }
}
